              id: "email",
              label: "Email address",
              value: state.values.email,
              placeholder: "jordan@example.com",
              required: true,
              type: "email",
              error: showError("email"),
              helperText: "We will send follow-up details to this email."
            })}

            ${FormField({
              id: "phone",
              label: "Phone number",
              value: state.values.phone,
              placeholder: "+1 (555) 123-4567",
              type: "tel",
              error: showError("phone"),
              helperText: "Optional. Use a format like +1 (555) 123-4567."
            })}

