<body>
  <div id="app"></div>

  <script>
    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      touched: {
        fullName: false,
        email: false,
        phone: false
      },
      submitted: false,
      statusMessage: ""
    };

    function validate(values) {
      const errors = {
        fullName: "",
        email: "",
        phone: ""
      };

      if (!values.fullName.trim()) {
        errors.fullName = "Full name is required.";
      }

      if (!values.email.trim()) {
        errors.email = "Email address is required.";
      } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
        errors.email = "Enter a valid email address.";
      }

      if (values.phone.trim() && !/^\+?[0-9\s().-]{7,20}$/.test(values.phone.trim())) {
        errors.phone = "Enter a valid phone number.";
      }

      return errors;
    }

    function FormField(props) {
      const { id, label, value, placeholder, required, error, helperText, type } = props;

      return `
        <div class="form-field">
          <div class="field-label-row">
            <label for="${id}">${label}</label>
            ${required ? '<span class="required-chip">Required</span>' : ""}
          </div>
          <input
            id="${id}"
            name="${id}"
            type="${type || "text"}"
            value="${escapeHtml(value)}"
            placeholder="${placeholder}"
            aria-invalid="${error ? "true" : "false"}"
            aria-describedby="${id}-helper ${id}-error"
            autocomplete="${id === "fullName" ? "name" : id === "email" ? "email" : "tel"}"
          />
          <p class="helper-text" id="${id}-helper">${helperText || ""}</p>
          <div class="validation-message" id="${id}-error">${error || ""}</div>
        </div>
      `;
    }

    function SupportContent() {
      return `
        <section class="hero-panel" aria-label="Support information">
          <div class="eyebrow">Support team</div>
          <h1>Let us help you solve it faster.</h1>
          <p>
            Share a few details and our support team will follow up with the right next steps for your account,
            billing, or product questions.
          </p>
          <ul class="info-list">
            <li><span class="info-dot"></span><span>Thoughtful support designed for customers who value clear, timely updates.</span></li>
            <li><span class="info-dot"></span><span>One streamlined form for the most common product and account issues.</span></li>
            <li><span class="info-dot"></span><span>Optional phone number if you want a callback from the team.</span></li>
          </ul>
        </section>
      `;
    }

    function ContactForm(errors) {
      const showError = (fieldName) => (state.touched[fieldName] || state.submitted ? errors[fieldName] : "");

      return `
        <section class="form-panel">
          <h2>Contact support</h2>
          <p class="intro">Tell us who you are and how we can reach you. Required fields are marked clearly.</p>
          <form id="support-form" novalidate>
            ${FormField({
              id: "fullName",
              label: "Full name",
              value: state.values.fullName,
              placeholder: "Jordan Lee",
              required: true,
              error: showError("fullName"),
              helperText: "Use the name associated with your account."
            })}

            ${FormField({
              id: "email",
              label: "Email address",
              value: state.values.email,
              placeholder: "jordan@example.com",
              required: true,
              type: "email",
              error: showError("email"),
              helperText: "We will send follow-up details to this email."
            })}

            ${FormField({
              id: "phone",
              label: "Phone number",
              value: state.values.phone,
              placeholder: "+1 (555) 123-4567",
              type: "tel",
              error: showError("phone"),
              helperText: "Optional. Use a format like +1 (555) 123-4567."
            })}

            <div class="actions">
              <button type="submit">Submit request</button>
              <div class="status-message" aria-live="polite">${state.statusMessage}</div>
            </div>
          </form>
        </section>
      `;
    }

    function App() {
      const errors = validate(state.values);

      return `
        <main class="page-shell">
          <div class="support-card">
            ${SupportContent()}
            ${ContactForm(errors)}
          </div>
        </main>
      `;
    }

    function attachEventHandlers() {
      const form = document.getElementById("support-form");

      ["fullName", "email", "phone"].forEach((fieldName) => {
        const input = document.getElementById(fieldName);

        input.addEventListener("input", (event) => {
          state.values[fieldName] = event.target.value;
          state.statusMessage = "";
          render();
        });

        input.addEventListener("blur", () => {
          state.touched[fieldName] = true;
          render();
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.submitted = true;
        state.touched.fullName = true;
        state.touched.email = true;
        state.touched.phone = true;

        const errors = validate(state.values);
        const hasErrors = Object.values(errors).some(Boolean);

        state.statusMessage = hasErrors
          ? ""
          : "Thanks! Your support request is ready to send.";

        render();
      });
    }

    function escapeHtml(value) {
      return String(value)
        .replaceAll("&", "&amp;")
        .replaceAll('"', "&quot;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;");
    }

    function render() {
      document.getElementById("app").innerHTML = App();
      attachEventHandlers();
    }

    render();
  </script>
